// Generated by scaffold-html-to-react-page (deterministic design transpile) from html/frontend/17-parent-login.html
// Structure + styling are faithful to the proto. DATA WIRING (fetch/list/handlers) is layered on after.
import { useState } from 'react';
import { ChevronUp, Delete, KeyRound, Shield } from 'lucide-react';
import { useScreenQuery } from '~/hooks/useScreenQuery';
import { useAppSelector } from '~/hooks/useAppSelector';
import '~/styles/protos/parent-login.css';

const BN_DIGITS = ['০', '১', '২', '৩', '৪', '৫', '৬', '৭', '৮', '৯'];

export default function ParentLoginPage() {
  const sessionUser = useAppSelector((s) => s.auth.user);
  const { data } = useScreenQuery(null);
  const [digits, setDigits] = useState('');
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);

  function pressDigit(bn: string) {
    const i = BN_DIGITS.indexOf(bn);
    const ascii = i >= 0 ? String(i) : bn;
    setError('');
    setDigits((d) => (d.length < 6 ? d + ascii : d));
  }

  async function verifyPin() {
    if (busy || digits.length !== 6) return;
    setBusy(true);
    setError('');
    const api = (import.meta.env.VITE_API_URL || '/api').replace(/\/api\/?$/, '');
    try {
      const res = await fetch(`${api}/api/parent/verify-pin`, {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ pin: digits }),
      });
      if (!res.ok) throw new Error('পিন ভুল হয়েছে। আবার চেষ্টা করুন।');
      window.location.assign('/parent');
    } catch (e) {
      setError(e instanceof Error ? e.message : 'পিন ভুল হয়েছে। আবার চেষ্টা করুন।');
      setDigits('');
      setBusy(false);
    }
  }

  return (
    <div data-testid="parent-login-page">
      <span className="sr-only" data-testid="screen-data-status">{data ? 'synced' : 'loading'}<span className="sr-only" data-testid="session-user">{sessionUser?.email ?? ''}</span></span>
      <main className="pl-shell" >
      
          <div className="pl-head">
            <span className="pl-mark" data-component="media" aria-hidden="true"><Shield  /></span>
            <h1 className="t-display-md" data-testid="plogin-heading">অভিভাবক প্রবেশ</h1>
            <p className="t-body-sm t-muted" data-testid="plogin-sub">৬ সংখ্যার পিন দিয়ে ঢুকুন</p>
          </div>
      
          <div>
            <div className="pl-dots" role="group" aria-label="পিনের অঙ্ক" aria-describedby="plogin-hint">
              {Array.from({ length: 6 }).map((_, i) => (
                <span
                  key={i}
                  className={'pl-dot' + (i < digits.length ? ' is-filled' : '')}
                  data-testid="plogin-dot"
                ></span>
              ))}
            </div>
            <p className="t-caption" id="plogin-hint" style={{ marginTop: 'var(--space-md)', textAlign: 'center' }} data-testid="plogin-hint">
              {error || 'ভুল হলে আবার দিতে পারবেন — ৩ বার ভুল হলে ১০ মিনিট বন্ধ থাকবে'}
            </p>
          </div>
      
          <div className="pl-keys" role="group" aria-label="সংখ্যা নির্বাচন">
            <button className="pl-key" type="button" data-testid="plogin-key" onClick={() => pressDigit('১')}>১</button>
            <button className="pl-key" type="button" data-testid="plogin-key" onClick={() => pressDigit('২')}>২</button>
            <button className="pl-key" type="button" data-testid="plogin-key" onClick={() => pressDigit('৩')}>৩</button>
            <button className="pl-key" type="button" data-testid="plogin-key" onClick={() => pressDigit('৪')}>৪</button>
            <button className="pl-key" type="button" data-testid="plogin-key" onClick={() => pressDigit('৫')}>৫</button>
            <button className="pl-key" type="button" data-testid="plogin-key" onClick={() => pressDigit('৬')}>৬</button>
            <button className="pl-key" type="button" data-testid="plogin-key" onClick={() => pressDigit('৭')}>৭</button>
            <button className="pl-key" type="button" data-testid="plogin-key" onClick={() => pressDigit('৮')}>৮</button>
            <button className="pl-key" type="button" data-testid="plogin-key" onClick={() => pressDigit('৯')}>৯</button>
            <button className="pl-key is-ghost" type="button" data-testid="plogin-key-blank" aria-hidden="true" disabled></button>
            <button className="pl-key" type="button" data-testid="plogin-key" onClick={() => pressDigit('০')}>০</button>
            <button className="pl-key" type="button" data-testid="plogin-key-delete" aria-label="মুছুন" onClick={() => setDigits((d) => d.slice(0, -1))}>
              <Delete  />
            </button>
          </div>
      
          <div className="ksr-stack">
            
            <button className="ksr-btn is-block" type="submit" data-testid="plogin-submit" onClick={verifyPin} disabled={busy}>প্যারেন্ট মোডে ঢোকো</button>
      
            
            <section className="ksr-panel" data-component="form" aria-labelledby="plogin-fallback-label">
              <button className="pl-expander" type="button" aria-expanded="true" aria-controls="plogin-fallback" data-testid="plogin-fallback-toggle">
                <KeyRound  />
                <span className="t-body-sm t-semibold ksr-grow" id="plogin-fallback-label">পিন মনে নেই?</span>
                <ChevronUp  />
              </button>
              <div id="plogin-fallback" className="pl-fields">
                <label className="field">
                  <span className="t-caption" data-testid="plogin-email-label">ইমেইল</span>
                  <input className="input" type="email" autoComplete="email" data-testid="plogin-email-input" />
                </label>
                <label className="field">
                  <span className="t-caption" data-testid="plogin-pass-label">পাসওয়ার্ড</span>
                  <input className="input" type="password" autoComplete="current-password" data-testid="plogin-pass-input" />
                </label>
              </div>
            </section>
          </div>
      
        </main>
    </div>
  );
}
